import{_ as a,o as i,c as l,a8 as n}from"./chunks/framework.CDZbtBrD.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[{"level":2,"title":"Unreleased","slug":"unreleased","link":"#unreleased","children":[{"level":3,"title":"Added","slug":"added","link":"#added","children":[]},{"level":3,"title":"Changed","slug":"changed","link":"#changed","children":[]},{"level":3,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":2,"title":"2.5.0 - 2026-11-02","slug":"_2-5-0-2026-11-02","link":"#_2-5-0-2026-11-02","children":[{"level":3,"title":"Added","slug":"added-1","link":"#added-1","children":[]},{"level":3,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]},{"level":3,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":2,"title":"2.0.0 - 2026-06-04","slug":"_2-0-0-2026-06-04","link":"#_2-0-0-2026-06-04","children":[{"level":3,"title":"Added","slug":"added-2","link":"#added-2","children":[]},{"level":3,"title":"Changed","slug":"changed-2","link":"#changed-2","children":[]},{"level":3,"title":"Fixed","slug":"fixed-2","link":"#fixed-2","children":[]}]},{"level":2,"title":"1.0.0 - 2026-01-19","slug":"_1-0-0-2026-01-19","link":"#_1-0-0-2026-01-19","children":[{"level":3,"title":"Added","slug":"added-3","link":"#added-3","children":[]},{"level":3,"title":"Changed","slug":"changed-3","link":"#changed-3","children":[]},{"level":3,"title":"Fixed","slug":"fixed-3","link":"#fixed-3","children":[]}]}],"relativePath":"CHANGELOG.md","filePath":"CHANGELOG.md"}'),t={name:"CHANGELOG.md"};function r(d,e,o,s,h,c){return i(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor link" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Notable changes to the EOPF Sentinel Zarr Explorer website. Versions follow <a href="https://semver.org/" class="link vp-external-link-icon" target="_blank" rel="noreferrer">SemVer</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/EOPF-Explorer/landing-page/compare/v2.5.0...HEAD" class="link vp-external-link-icon" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor link" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor link" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Allow bands manipulation and arithemtics on the Mosaic view</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor link" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Updated privacy policy data retention period (⁠<a href="https://github.com/EOPF-Explorer/landing-page/pull/134" class="link vp-external-link-icon" target="_blank" rel="noreferrer">https://github.com/EOPF-Explorer/landing-page/pull/134</a>)</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor link" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><h2 id="_2-5-0-2026-11-02" tabindex="-1"><a href="https://github.com/EOPF-Explorer/landing-page/compare/v2.0.0...v2.5.0" class="link vp-external-link-icon" target="_blank" rel="noreferrer">2.5.0</a> - 2026-11-02 <a class="header-anchor link" href="#_2-5-0-2026-11-02" aria-label="Permalink to &quot;[2.5.0] - 2026-11-02&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor link" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Developer Resources page covering the STAC, raster and openEO APIs, direct Zarr access and the data model, linked from the navigation, the home page and Software &amp; Services (#126).</li><li>&quot;Build with EOPF Zarr&quot; section on the home page featuring six software and services (#123).</li><li><code>llms.txt</code>, <code>llms-full.txt</code> and a Markdown copy of each page for LLM clients (#126), including the service, event and tutorial lists (#130).</li><li>Support for client side rendering and filtering of Sentinel-1 &amp; Sentinel-3 in the Dynamic Browser: catalog filters and hover details follow the selected collection, and the browser opens on all collections (#108).</li><li>STAC item links open the Dynamic Browser with the item selected (#108).</li><li>ol-stac in Software &amp; Services (#126).</li><li>Banner for planned service interruptions (#127).</li><li>Webinar #3 page (#128, #131) and the FOSS4G Europe 2026 workshop (#109).</li><li>Privacy notice and an updated cookie notice (#106).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor link" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Dynamic Browser catalog items show mission, product level, date and tile instead of truncated product IDs (#122).</li><li>Software &amp; Services cards are clickable as a whole, and external links across the site are marked (#122).</li><li>Home page sections reordered (#125).</li><li>openEO Web Editor removed from Software &amp; Services, and service entries updated (#112, #126).</li><li>Updated to eodash 5.10 and pages-theme-eox 2.0 (#108, #126).</li><li>Performance enhancements for the Dynamic Browser.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor link" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Software &amp; Services sometimes rendering empty until a refresh (#122).</li><li>Keyword search in the Software &amp; Services gallery (#122, #126).</li><li>Dynamic Browser: the date picker now recenters the timeline (#126); mosaic view hints when there is no data in view, item click and hover work reliably, and the time slider no longer glitches (#104).</li><li>Feature matrix icons no longer look like separate buttons (#122).</li><li>Example STAC items on the tutorial pages are resolved at build time, so expired items no longer break them (#115).</li><li>Broken and outdated links, including the webinar slides, the CarbonPlan demo and the NDCI story image (#111, #114, #119, #122, #123).</li><li>Inconsistent FAQ typography (#126).</li></ul><h2 id="_2-0-0-2026-06-04" tabindex="-1"><a href="https://github.com/EOPF-Explorer/landing-page/compare/v1.0.0...v2.0.0" class="link vp-external-link-icon" target="_blank" rel="noreferrer">2.0.0</a> - 2026-06-04 <a class="header-anchor link" href="#_2-0-0-2026-06-04" aria-label="Permalink to &quot;[2.0.0] - 2026-06-04&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor link" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Client-side GeoZarr rendering in the Sentinel Explorer (#101, #103).</li><li>Sentinel Explorer: STAC item details, sorting, tooltips, date range selection and 3D terrain (#62); the mosaic follows the timeline filters, including cloud cover (#49); the item catalog is available in compare mode (#46).</li><li>GeoZarr Data Model page with a timeline, featured on the home page (#38).</li><li>EOxElements and eodash tutorial pages and catalog entries (#60), and EOxElements Jupyter with Python examples for the EOxElements tutorials (#99).</li><li>STAC demo page built with OpenLayers (#59), and openEO Studio in Software &amp; Services (#52, #71).</li><li>Webinars &amp; Events page (#80), a webinar registration button and ThriveGEO in the acknowledgments (#72).</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor link" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Software &amp; Services pages moved under <code>/software-services/</code> with a shared tutorial layout (#60).</li><li>OpenLayers 10.9, titiler-eopf 0.8 and updated GeoZarr source configurations across the site (#74, #91, #103).</li><li>Software &amp; Services entries follow a fixed order (#44).</li><li>Webinar #2 links to its recording (#102).</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor link" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Sentinel Explorer: loading bar position, switching between the 3D globe and the 2D map, the mosaic in the expert template and the band arithmetic forms (#46); map and globe performance, timeline time slots and hiding a scene by selecting it again (#62); item order and selected item highlighting (#103).</li><li>TiTiler tile scaling (#103).</li><li>Zarr URLs include the measurements path (#91).</li><li>Styling that did not follow the page theme (#48).</li><li>Spelling and typing errors (#45, #50).</li></ul><h2 id="_1-0-0-2026-01-19" tabindex="-1"><a href="https://github.com/EOPF-Explorer/landing-page/releases/tag/v1.0.0" class="link vp-external-link-icon" target="_blank" rel="noreferrer">1.0.0</a> - 2026-01-19 <a class="header-anchor link" href="#_1-0-0-2026-01-19" aria-label="Permalink to &quot;[1.0.0] - 2026-01-19&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor link" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Landing page for the EOPF Sentinel Zarr Explorer, based on the V0 design (#2, #15) and the EOPF brand (#9), with a feature matrix and a link to the EOPF forum (#22).</li><li>Sentinel Explorer dashboard built on eodash (#6), with an easier-to-scan scene list, a base map that loads first and a loading indicator (#37).</li><li>Story viewer for narratives (#14).</li><li>Software &amp; Services catalog with search, tags and category filters that can be set from the URL (#29, #34, #36, #40).</li><li>TiTiler and OpenLayers integration examples (#30, #31).</li><li>Preview deployments for pull requests (#8).</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor link" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Pre-release notice shown during the soft launch (#4) and removed for the public launch (#13).</li><li>Tagline aligned with the logo (#22).</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor link" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Sentinel Explorer not loading when opened directly by URL (#20), and the eodash page layout (#24).</li><li>Base URL and broken links (#7, #12, #18).</li></ul>',29)])])}const p=a(t,[["render",r]]);export{u as __pageData,p as default};
